function refreshUnifinderFilterInterval() {
  const view = currentView();
  const today = cal.dtz.now();
  today.isDate = true;

  let startDate, endDate;

  const intervalSelection = document.getElementById("event-filter-menulist").selectedItem.value;
  switch (intervalSelection) {
    case "past":
      startDate = today.clone();
      // Use last 100 yrs instead of unbounded value, to avoid performance
      // issues with recurring events.
      startDate.year -= 100;
      endDate = today;
      break;
    case "today":
      startDate = today;
      endDate = today.clone();
      endDate.day++;
      break;
    case "P7D":
      startDate = today;
      endDate = today.clone();
      endDate.day += 7;
      break;
    case "P14D":
      startDate = today;
      endDate = today.clone();
      endDate.day += 14;
      break;
    case "P31D":
      startDate = today;
      endDate = today.clone();
      endDate.day += 31;
      break;
    case "next6Months":
      startDate = today;
      endDate = today.clone();
      endDate.month += 6;
      break;
    case "next12Months":
      startDate = today;
      endDate = today.clone();
      endDate.month += 12;
      break;
    case "future":
      // Use next 100 yrs instead of unbounded values, to avoid performance
      // issues with recurring events.
      startDate = today.clone();
      endDate = today.clone();
      endDate.year += 100;
      break;
    case "thisCalendarMonth":
      startDate = today.startOfMonth;
      endDate = today.endOfMonth;
      endDate.day++;
      break;
    case "current":
      startDate = view.selectedDay;
      endDate = startDate.clone();
      endDate.day++;
      break;
    case "currentview":
      startDate = view.startDate;
      endDate = view.endDate;
      break;
    case "all":
      // Use last +-100 yrs instead of unbounded values, to avoid performance
      // issues with recurring events.
      startDate = today.clone();
      startDate.year -= 100;
      endDate = today.clone();
      endDate.year += 100;
      break;
  }

  const filteredView = getUnifinderView();
  if (filteredView) {
    filteredView.setDateRange(startDate, endDate);
    filteredView.refreshItems();
  }
}
